{"action":"run_code","code":"const repo = 'acme/cli';
const label = 'needs-triage';
const candidates = new Set<number>();
let page: number | null = 1;
while (page !== null) {
  const issues = await tools.list_issues({ repo, state: 'open', page });
  for (const issue of issues.items) {
    if (issue.state === 'open' && issue.labels.length === 0) candidates.add(issue.number);
  }
  page = issues.next_page;
}
return await Promise.allSettled([...candidates].map(async number => {
  const issue = await tools.get_issue({ repo, number });
  if (issue.state !== 'open' || issue.labels.length !== 0) return { number, updated: false };
  const result = await tools.add_label({ repo, number, label });
  if (result.number !== number || !result.labels.some(item => item.name === label)) {
    throw new Error(`Could not confirm label on issue #${number}`);
  }
  return { number, updated: true };
})).then(results => results.map(result => result.status === 'fulfilled' ? result.value : { error: String(result.reason) }));","answer":""}

